'use strict';document.getElementById('user-login').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),error=document.getElementById('error');error.textContent='';b.disabled=true;b.textContent='正在登录…';try{const r=await fetch('/api/user/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.error?.message||'登录失败');try{localStorage.removeItem('golfera-demo-v1');}catch{}const next=new URLSearchParams(location.search).get('next');const target=next&&/^\/index\.html(?:#[A-Za-z0-9_./:-]*)?$/.test(next)?next:'/index.html#me';location.replace(target);}catch(e){error.textContent=e instanceof TypeError?'网络连接失败，请检查网络后重试':e.message;}finally{b.disabled=false;b.textContent='登录';}});
